    @Synchronized fun economy_transfer(from: String, to: String, amount: Long, key: String?): Boolean {
      try {
        if (key != null) {
          var dup = false
          economy_db.prepareStatement("SELECT 1 FROM ledger WHERE key = ?").use { ps ->
            ps.setString(1, key)
            ps.executeQuery().use { rs ->
              dup = rs.next()
            }
          }
          if (dup) {
            return true
          }
        }
        if (amount <= 0L) {
          return false
        }
        economy_db.createStatement().use { st ->
          st.execute("BEGIN IMMEDIATE")
          try {
            var curFrom = 0L
            economy_db.prepareStatement("SELECT balance FROM balances WHERE user = ?").use { ps ->
              ps.setString(1, from)
              ps.executeQuery().use { rs ->
                curFrom = if (rs.next()) rs.getString(1).toLong() else 0L
              }
            }
            val fromBalance = curFrom
            if (fromBalance < amount) {
              st.execute("ROLLBACK")
              return false
            }
            val nextFrom = NewrRt.sub(fromBalance, amount)
            economy_db.prepareStatement("INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance").use { ps ->
              ps.setString(1, from)
              ps.setString(2, (nextFrom).toString())
              ps.executeUpdate()
            }
            if (key != null) {
              economy_db.prepareStatement("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)").use { ps ->
                ps.setString(1, from)
                ps.setString(2, (NewrRt.sub(0L, amount)).toString())
                ps.setString(3, key)
                ps.setLong(4, System.currentTimeMillis() / 1000)
                ps.executeUpdate()
              }
            }
            // Heal the receiver's ledger: a previous failed transfer may have logged the out leg but not the in leg; replay it with the opposite key before crediting.
            var healed = false
            var sumOut = 0L
            var sumIn = 0L
            var sumKeys = 0L
            economy_db.prepareStatement("SELECT amount, key FROM ledger WHERE user = ?").use { ps ->
              ps.setString(1, to)
              ps.executeQuery().use { rs ->
                while (rs.next()) {
                  val k = rs.getString(2)
                  val a = rs.getString(1).toLong()
                  if (k != null && k.endsWith(":out")) {
                    sumOut = NewrRt.add(sumOut, a)
                  } else if (k != null && k.endsWith(":in")) {
                    sumIn = NewrRt.add(sumIn, a)
                  } else {
                    sumKeys = NewrRt.add(sumKeys, a)
                  }
                }
              }
            }
            if (sumOut > 0L && sumIn == 0L) {
              val heal = minOf(amount, sumOut)
              economy_db.prepareStatement("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)").use { ps ->
                ps.setString(1, to)
                ps.setString(2, heal.toString())
                ps.setString(3, if (key != null) key + ":in" else null)
                ps.setLong(4, System.currentTimeMillis() / 1000)
                ps.executeUpdate()
              }
              healed = true
            }
            var curTo = 0L
            economy_db.prepareStatement("SELECT balance FROM balances WHERE user = ?").use { ps ->
              ps.setString(1, to)
              ps.executeQuery().use { rs ->
                curTo = if (rs.next()) rs.getString(1).toLong() else 0L
              }
            }
            val toBalance = curTo
            val nextTo = NewrRt.add(toBalance, amount)
            if (!healed) {
              economy_db.prepareStatement("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)").use { ps ->
                ps.setString(1, to)
                ps.setString(2, (amount).toString())
                ps.setString(3, if (key != null) key + ":in" else null)
                ps.setLong(4, System.currentTimeMillis() / 1000)
                ps.executeUpdate()
              }
            }
            economy_db.prepareStatement("INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = excluded.balance").use { ps ->
              ps.setString(1, to)
              ps.setString(2, (nextTo).toString())
              ps.executeUpdate()
            }
