  private lateinit var bot: Bot

  private lateinit var kord: Kord

  private val buttonHandlers = mutableMapOf<String, suspend (ButtonInteraction) -> Unit>()
  private val _componentAuthors = ConcurrentHashMap<String, String>()

  init {
    buttonHandlers["buy-again"] = ::buyAgainHandler
  }

  private val _DEFAULT_LOCALE = "en"
  private val STRINGS: LinkedHashMap<String, LinkedHashMap<String, String>> = _newrStrings()

  private fun _newrStrings(): LinkedHashMap<String, LinkedHashMap<String, String>> {
    val m = linkedMapOf<String, LinkedHashMap<String, String>>()
    m["en"] = NewrRt.dictOf<String>("buy.ok", "Bought {item} for {price} gold. Balance: {balance}.", "buy.poor", "Not enough gold — {item} costs {price}, you have {balance}.")
    m["id"] = NewrRt.dictOf<String>("buy.ok", "Membeli {item} seharga {price} gold. Saldo: {balance}.", "buy.poor", "Gold tidak cukup — {item} harganya {price}, kamu punya {balance}.")
    return m
  }

  private fun _t(key: String, locale: String, vars: Map<String, Any?>): String {
    var table = STRINGS[locale]
    if (table == null && locale.contains("-")) {
      table = STRINGS[locale.split("-")[0]]
    }
    if (table == null) {
      table = STRINGS[_DEFAULT_LOCALE]
    }
    val template = table?.get(key) ?: return key
    var out = template
    for (e in vars.entries) {
      out = out.replace("{" + e.key + "}", NewrRt.toStr(e.value))
    }
    return out
  }

