  fun _newrRegisterGuild(builder: GuildMultiApplicationCommandBuilder) {
    builder.input("ping", "Answer with pong") { _newrCmdPing(this) }
    builder.input("buy", "Buy an item from the shop") { _newrCmdBuy(this) }
    builder.input("balance", "Show your balance") { _newrCmdBalance(this) }
