  private suspend fun executePing(interaction: ChatInputCommandInteraction) {
    val _newrGuild: Guild? = (interaction as? GuildInteraction)?.getGuildOrNull()
    val _newrChannel: MessageChannel = interaction.getChannel()
    interaction.respondPublic { content = "Pong! Hello " + interaction.user.mention };
  }

  private suspend fun executeBuy(interaction: ChatInputCommandInteraction) {
    val _newrGuild: Guild? = (interaction as? GuildInteraction)?.getGuildOrNull()
    val _newrChannel: MessageChannel = interaction.getChannel()
    var item: String = interaction.command.strings["item"]!!
    var amount: Long = interaction.command.integers["amount"] ?: 1L
    var price: Long = NewrRt.mul(shop_items.price_of(item), amount);
    var bal: Long = bot.economy_balance(interaction.user.id.value.toString());
    if (bal < price) {
      interaction.respondEphemeral { content = _t("buy.poor", _newrLocale(interaction.locale), NewrRt.dictOf<Any?>("price", price, "balance", bal, "item", item)) };
    } else {
      bot.economy_credit(interaction.user.id.value.toString(), NewrRt.neg(price), "buy-" + interaction.user.id.value + "-" + item + "-" + amount);
      val _newr_c0_row = ActionRowBuilder().apply {
        interactionButton(ButtonStyle.Primary, "buy-again") { label = "Buy again" }
      }
      interaction.respondPublic { content = _t("buy.ok", _newrLocale(interaction.locale), NewrRt.dictOf<Any?>("item", item, "price", price, "balance", NewrRt.sub(bal, price))) ; components = mutableListOf(_newr_c0_row) };
      val _newr_c0_message = interaction.getOriginalInteractionResponse()
      _componentAuthors[_newr_c0_message.id.value.toString() + ":" + "buy-again"] = interaction.user.id.value.toString()
      kord.launch {
        delay(60L * 1000L)
        try {
          _newr_c0_message.edit { components = mutableListOf() }
          _newr_c0_message.edit { content = "Offer expired." };
          _componentAuthors.remove(_newr_c0_message.id.value.toString() + ":" + "buy-again")
        } catch (e: Exception) {
          System.err.println("[timeout] " + e)
        }
      }
    }
  }

  private suspend fun executeBalance(interaction: ChatInputCommandInteraction) {
    val _newrGuild: Guild? = (interaction as? GuildInteraction)?.getGuildOrNull()
    val _newrChannel: MessageChannel = interaction.getChannel()
    interaction.respondPublic { content = "Balance: " + bot.economy_balance(interaction.user.id.value.toString()) + " gold." };
  }

  private suspend fun buyAgainHandler(interaction: ButtonInteraction) {
    val _newrGuild: Guild? = (interaction as? GuildInteraction)?.getGuildOrNull()
    val _newrChannel: MessageChannel = interaction.getChannel()
    val _newrAuthorId = _componentAuthors[interaction.message.id.value.toString() + ":" + "buy-again"]
    if (_newrAuthorId != null && interaction.user.id.value.toString() != _newrAuthorId) {
      interaction.respondEphemeral { content = "This button is not for you." }
      return
    }
    interaction.respondPublic { content = "Use /buy again, " + interaction.user.mention + "!" };
  }

  private suspend fun _every_1h() {
    System.out.println("Hourly shop check ran");
  }

  private suspend fun onReady(event: ReadyEvent) {
    System.out.println("" + kord.getSelf().tag + " is online");
  }

  private suspend fun onMemberJoin(event: MemberJoinEvent) {
    val _newrSystemChannel: MessageChannel? = event.member.getGuild().getSystemChannel()
    if (_newrSystemChannel != null) {
      _newrSystemChannel.createMessage { content = "Welcome to " + event.member.getGuild().name + ", " + event.member.mention + "!" };
    }
  }

  @OptIn(PrivilegedIntent::class)
  fun main(args: Array<String>) {
    runBlocking {
      val _newrToken = System.getenv("DISCORD_TOKEN") ?: ""
      if (_newrToken.isEmpty()) {
        throw IllegalStateException("set the DISCORD_TOKEN environment variable")
      }
      bot = Bot()
      bot.setup()
      kord = Kord(_newrToken)
      kord.on<ReadyEvent> { onReady(this) }
      kord.on<MemberJoinEvent> { onMemberJoin(this) }
      kord.on<ChatInputCommandInteractionCreateEvent> {
        val interaction = this.interaction
        try {
          when (interaction.invokedCommandName) {
            "ping" -> executePing(interaction)
            "buy" -> executeBuy(interaction)
            "balance" -> executeBalance(interaction)
          }
        } catch (e: Exception) {
          System.err.println("[dispatch] /" + interaction.invokedCommandName + " failed: " + e)
          try {
            interaction.respondEphemeral { content = "Something went wrong running that command. Try again in a moment." }
          } catch (replyError: Exception) {
            try {
              FollowupPermittingInteractionResponseBehavior(interaction.applicationId, interaction.token, kord, kord.defaultSupplier).createEphemeralFollowup { content = "Something went wrong running that command. Try again in a moment." }
            } catch (followupError: Exception) {
              System.err.println("[dispatch] could not send the error reply: " + followupError)
            }
          }
        }
      }
      kord.on<ButtonInteractionCreateEvent> {
        buttonHandlers[this.interaction.componentId]?.invoke(this.interaction)
      }
      kord.launch {
        while (true) {
          delay(3600000L)
          try {
            _every_1h()
          } catch (e: Throwable) {
            System.err.println(e)
          }
        }
      }
      kord.login {
        intents {
          +Intent.GuildMembers
          +Intent.Guilds
        }
      }
    }
  }

  private fun _newrLocale(locale: Locale?): String {
    if (locale == null) {
      return ""
    }
    val country = locale.country
    return if (country.isNullOrEmpty()) locale.language else locale.language + "-" + country
  }
